input.command:
cd /tmp/w
t() { echo "### CMD: $*"; out=$("$@" </dev/null 2>/tmp/.e); rc=$?; echo "EXIT=$rc"; [ -n "$out" ] && { echo "OUT:"; printf '%s\n' "$out" | cat -A | head -8; }; [ -s /tmp/.e ] && { echo "ERR:"; cat -A /tmp/.e; }; echo; }
for v in 0 1 4 -1 abc 3.5 "" 999999999999999999999 +5 " 4"; do t /workspace/executable --tabs="$v" /tmp/w/a.txt; done

cd /tmp/w
t() { echo "### CMD: $*"; out=$("$@" </dev/null 2>/tmp/.e8); rc=$?; echo "EXIT=$rc"; [ -n "$out" ] && { echo "OUT:"; printf '%s\n' "$out" | cat -A | head -12; }; [ -s /tmp/.e8 ] && { echo "ERR:"; cat -A /tmp/.e8 | head -12; }; echo; }
for f in --config-file --config-dir --cache-dir --generate-config-file --no-config --no-custom-assets --lessopen --no-lessopen --no-paging --no-pager -P --list-themes --list-languages -L --strip-ansi --set-terminal-title --unbuffered -u -E --quiet-empty --show-all -A -s --squeeze-blank -S --chop-long-lines -f --force-colorization -d --diff --plain --number; do
  case $f in
    --generate-config-file|--list-themes|--list-languages|-L) echo "### (skipping side-effect run for $f, tested separately)"; continue;;
    --strip-ansi) t /workspace/executable --strip-ansi=never /tmp/w/a.txt; continue;;
  esac
  t /workspace/executable $f /tmp/w/a.txt
done
